// One-off generator: mirrors exam-profiles.mjs (the canonical shared
// source) into shared/exam-profiles.js, a plain non-module <script> the
// browser tools (long-post-factory, update-factory) load directly — so
// there is exactly one hand-maintained copy of EXAM_PROFILES, never three.
// Re-run this any time exam-profiles.mjs changes; do not hand-edit the
// generated file.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, '..', '..', '..');
const src = fs.readFileSync(path.join(__dirname, 'exam-profiles.mjs'), 'utf8');

const body = src.replace(/^export /gm, '');

const out = `// AUTO-GENERATED by gen-exam-profiles-browser.mjs from
// Automation/core/src/exam-profiles.mjs. Do not hand-edit — re-run the
// generator instead so this never drifts from the canonical source.
// Exposes window.ExamProfiles = { EXAM_PROFILES, getExamProfile, genericExamProfile }.
(function(global){
${body}
global.ExamProfiles = { EXAM_PROFILES, getExamProfile, genericExamProfile };
})(typeof window !== 'undefined' ? window : this);
`;

const outDir = path.join(REPO_ROOT, 'shared');
fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(path.join(outDir, 'exam-profiles.js'), out);
console.log('wrote shared/exam-profiles.js');
